-- Transactional integration tests: all users and data are rolled back.
begin;
do $$
declare admin_id uuid:=gen_random_uuid(); ref1 uuid:=gen_random_uuid(); ref2 uuid:=gen_random_uuid(); referral_id uuid; hire_id uuid; retention_id uuid; comm_id uuid; result jsonb; s jsonb; x jsonb; count_rows int; rejected boolean; first_month date:=(date_trunc('month',current_date)-interval '6 months')::date; inv text:='qa-invoice'; referral_code text;
begin
 insert into evzon_private.admin_bootstrap(email) values('qa-admin-'||admin_id||'@example.invalid');
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values(admin_id,'qa-admin-'||admin_id||'@example.invalid',now(),'{"name":"QA Admin"}');
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values(ref1,'qa-ref1-'||ref1||'@example.invalid',now(),'{"name":"QA Referrer One","role":"ADMIN"}'),(ref2,'qa-ref2-'||ref2||'@example.invalid',now(),'{"name":"QA Referrer Two"}');
 if (select role from public.evzon_profiles where id=ref1)<>'REFERRER' or (select status from public.evzon_profiles where id=ref1)<>'Pending' then raise exception 'FAIL: public signup role'; end if;
 if not exists(select 1 from public.evzon_profiles where id=admin_id and role='ADMIN' and status='Approved') then raise exception 'FAIL: verified bootstrap'; end if;
 update public.evzon_profiles set status='Approved' where id in (ref1,ref2);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ref1,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 result:=public.evzon_command('submit','{"name":"QA Candidate","email":"qa-candidate@example.invalid","consent":true}');
 referral_id:=(result->'referrals'->0->>'id')::uuid;
 if referral_id is null then raise exception 'FAIL: submission'; end if;
 rejected:=false;begin perform public.evzon_command('account',jsonb_build_object('id',ref1,'role','ADMIN','status','Approved'));exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL: self elevation'; end if;
 rejected:=false;begin update public.evzon_profiles set role='ADMIN' where id=ref1;exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'FAIL: direct role update'; end if;
 select count(*) into count_rows from public.evzon_workspace;if count_rows<>0 then raise exception 'FAIL: referrer workspace isolation';end if;
 select count(*) into count_rows from public.evzon_profiles;if count_rows<>1 then raise exception 'FAIL: profiles isolation';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ref2,'role','authenticated')::text,true);
 result:=public.evzon_portal();if jsonb_array_length(result->'referrals')<>0 or jsonb_array_length(result->'contacts')<>0 then raise exception 'FAIL: other referrer data isolation';end if;
 select count(*) into count_rows from public.evzon_referrals;if count_rows<>0 then raise exception 'FAIL: direct table referral isolation';end if;
 execute 'reset role';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 s:=jsonb_build_object('version',1,'workers',jsonb_build_array(jsonb_build_object('id','qa-worker','name','QA Candidate','status','Active','payroll','Monthly salary','referrerId',ref1,'referralId',referral_id,'start',first_month)),'team','[]'::jsonb,'expenses','[]'::jsonb,'agencies','[]'::jsonb,'invoices',jsonb_build_array(jsonb_build_object('id',inv,'amount',1000)),'payments','[]'::jsonb,'actualExpenses',jsonb_build_array(jsonb_build_object('id','qa-pay','worker','qa-worker','category','Worker payroll','amount',750,'date',first_month)),'shifts','[]'::jsonb,'applicants','[]'::jsonb,'history','[]'::jsonb,'snapshots','[]'::jsonb,'earnings',jsonb_build_array(jsonb_build_object('id','qa-earned','worker','qa-worker','hourly',800,'commission',200,'date',first_month,'invoice',inv)),'settings','{}'::jsonb,'scenarios','[]'::jsonb);
 execute 'set local role authenticated';
 result:=public.evzon_command('save',jsonb_build_object('revision',0,'state',s));
 if (select count(*) from public.evzon_rewards where status='Pending review')<>0 then raise exception 'FAIL: training alone or unverified hiring rewarded';end if;
 result:=public.evzon_command('referral',jsonb_build_object('id',referral_id,'stage','Hired','training_complete',true,'assessment_passed',true,'hired_on',first_month,'reason',''));
 select id into hire_id from public.evzon_rewards where worker_id='qa-worker' and kind='Hire';
 if (select amount from public.evzon_rewards where id=hire_id)<>20 or (select status from public.evzon_rewards where id=hire_id)<>'Pending review' then raise exception 'FAIL: hire qualification';end if;
 result:=public.evzon_command('refresh','{}');result:=public.evzon_command('refresh','{}');
 if (select count(*) from public.evzon_rewards where worker_id='qa-worker' and kind='Hire')<>1 then raise exception 'FAIL: duplicate hire reward';end if;
 -- 29 attended days and one absence do not satisfy 30 active days.
 s:=jsonb_set(s,'{shifts}',(select jsonb_agg(jsonb_build_object('id','day-'||g,'worker','qa-worker','date',first_month+g,'actual',8,'overtime',0,'approved',true,'absence',g=30,'replacement','')) from generate_series(1,30) g));
 result:=public.evzon_command('save',jsonb_build_object('revision',1,'state',s));
 if (select active_days from public.evzon_referrals where id=referral_id)<>29 then raise exception 'FAIL: active attendance count';end if;
 if exists(select 1 from public.evzon_rewards where kind='Retention' and status<>'Not yet eligible') then raise exception 'FAIL: early retention';end if;
 result:=public.evzon_command('workday',jsonb_build_object('worker_id','qa-worker','day',first_month+30,'reason','Reviewed attendance correction'));
 select id into retention_id from public.evzon_rewards where kind='Retention' and worker_id='qa-worker';
 if (select amount from public.evzon_rewards where id=retention_id)<>30 or (select status from public.evzon_rewards where id=retention_id)<>'Pending review' then raise exception 'FAIL: retention qualification';end if;
 result:=public.evzon_command('finalize',jsonb_build_object('worker_id','qa-worker','period',first_month,'confirmed',true));
 select id into comm_id from public.evzon_rewards where kind='Commission' and worker_id='qa-worker';
 if (select amount from public.evzon_rewards where id=comm_id)<>12.5 then raise exception 'FAIL: commission formula';end if;
 result:=public.evzon_command('reward',jsonb_build_object('id',comm_id,'status','Approved'));
 rejected:=false;begin perform public.evzon_command('reward',jsonb_build_object('id',comm_id,'status','Paid','payment_reference','test before collection'));exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL: uncollected commission payable';end if;
 -- Frozen month cannot have its compensation rewritten.
 x:=jsonb_set(s,'{actualExpenses,0,amount}','1');rejected:=false;
 begin perform public.evzon_command('save',jsonb_build_object('revision',2,'state',x));exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL: closed period rewritten';end if;
 s:=jsonb_set(s,'{payments}',jsonb_build_array(jsonb_build_object('id','receipt','invoice',inv,'amount',1000,'date',current_date)));
 result:=public.evzon_command('save',jsonb_build_object('revision',2,'state',s));
 result:=public.evzon_command('reward',jsonb_build_object('id',comm_id,'status','Paid','payment_reference','QA payment 1'));
 result:=public.evzon_command('reward',jsonb_build_object('id',comm_id,'status','Paid','payment_reference','QA duplicate retry'));
 execute 'reset role';
 if (select count(*) from evzon_private.payouts where reward_id=comm_id)<>1 then raise exception 'FAIL: duplicate payout';end if;
 -- Negative contribution and the seventh calendar month never earn a commission.
 insert into evzon_private.periods(worker_id,period,revenue,compensation,invoices,finalized_by) values('qa-worker',first_month+interval '1 month',100,200,array[inv],admin_id),('qa-worker',first_month+interval '6 months',1000,100,array[inv],admin_id);
 execute 'set local role authenticated';result:=public.evzon_command('refresh','{}');
 if (select count(*) from public.evzon_rewards where worker_id='qa-worker' and kind='Commission')<>1 then raise exception 'FAIL: negative or expired commission';end if;
 result:=public.evzon_command('config','{"hire_bonus":99,"retention_bonus":88,"retention_days":20,"commission_rate":10,"commission_months":12,"require_collected":true,"resources":"QA prospective settings"}');
 if (select amount from public.evzon_rewards where id=hire_id)<>20 or (select (terms->>'commission_rate')::numeric from public.evzon_referrals where id=referral_id)<>5 then raise exception 'FAIL: settings retroactively changed';end if;
 rejected:=false;begin perform public.evzon_command('save',jsonb_build_object('revision',1,'state',s));exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL: revision conflict';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ref2,'role','authenticated')::text,true);
 select count(*) into count_rows from public.evzon_rewards;if count_rows<>0 then raise exception 'FAIL: rewards isolation';end if;
 rejected:=false;begin perform public.evzon_command('reward',jsonb_build_object('id',comm_id,'status','Paid'));exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL: referrer payout access';end if;
 execute 'reset role';update public.evzon_profiles set status='Suspended' where id=ref1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ref1,'role','authenticated')::text,true);execute 'set local role authenticated';
 select count(*) into count_rows from public.evzon_referrals;if count_rows<>0 then raise exception 'FAIL: suspension isolation';end if;
 execute 'reset role';select code into referral_code from public.evzon_profiles where id=ref2;perform set_config('request.jwt.claims','{}',true);execute 'set local role anon';
 rejected:=false;begin perform public.evzon_portal();exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'FAIL: anonymous portal access';end if;
 rejected:=false;begin perform public.evzon_apply(referral_code,'{}');exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'FAIL: legacy anonymous entry point remains enabled';end if;
 execute 'reset role';
 perform set_config('evzon.test_results','PASS: database integration assertions — role defaults, verified bootstrap, submission, role escalation, private workspace, profile/referral/reward isolation, hire qualification, idempotence, active-day attendance, retention, positive commission, collection gate, closed-period immutability, duplicate payment, negative and expired commission, prospective settings, revision conflict, payout authorization, suspension, anonymous denial, legacy anonymous entry point disabled',true);
end $$;
select current_setting('evzon.test_results') as result;
rollback;
